replace into madsAuthorityUpdate (id, lccn, vocabulary, recordStatus, heading, headingType, isSubdivision, undifferentiated, moddate, addedDate, numUpdates, source) values ("http://id.loc.gov/authorities/genreForms/gf2010025067", "gf2010025067", 3, 1, "Gravity anomaly maps", 5, false, false, "2012-03-29T08:31:40", "2026-08-26", "2", '{"@graph":[{"@id":"_:b34iddOtlocdOtgovauthoritiesgenreFormsgf2010025067","@type":"madsrdf:Source","madsrdf:citationStatus":"found","madsrdf:citationSource":"Introduction to potential fields: gravity, 1997:","madsrdf:citationNote":{"@language":"en","@value":"p. 2 (a gravity map is made using numerous gravity measurements across the area of interest ... gravity measurements are often processed to a complete-Bouguer or isostatic gravity anomaly. These data are then gridded, so that the randomly spaced data are converted to a representation of the gravity field at equally spaced locations)"}},{"@id":"_:b42iddOtlocdOtgovauthoritiesgenreFormsgf2010025067","@type":"madsrdf:Source","madsrdf:citationStatus":"found","madsrdf:citationSource":"Gravity anomaly maps, via Wisconsin State Cartographer''s Office website, July 16, 2010","madsrdf:citationNote":{"@language":"en","@value":"(Gravity anomaly maps depict the difference between theoretical computed gravity values and observed gravity values for a region of the earth''s crust)"}},{"@id":"_:b28iddOtlocdOtgovauthoritiesgenreFormsgf2010025067","@type":"madsrdf:Source","madsrdf:citationStatus":"found","madsrdf:citationSource":"GRACE gravity map image gallery, via WWW, July 16, 2010."},{"@id":"_:b64iddOtlocdOtgovauthoritiesgenreFormsgf2010025067","@type":"ri:RecordInfo","ri:recordChangeDate":{"@type":"xsd:dateTime","@value":"2011-10-19T00:00:00"},"ri:recordStatus":{"@type":"xsd:string","@value":"new"},"ri:recordContentSource":{"@id":"http://id.loc.gov/vocabulary/organizations/wau"},"ri:languageOfCataloging":{"@id":"http://id.loc.gov/vocabulary/iso639-2/eng"}},{"@id":"_:b50iddOtlocdOtgovauthoritiesgen