.gov/authorities/genreForms/gf2011026610"},{"@id":"http://id.loc.gov/authorities/genreForms/gf2011026613"},{"@id":"http://id.loc.gov/authorities/genreForms/gf2011026617"},{"@id":"http://id.loc.gov/authorities/genreForms/gf2011026690"},{"@id":"http://id.loc.gov/authorities/genreForms/gf2011026697"},{"@id":"http://id.loc.gov/authorities/genreForms/gf2011026699"},{"@id":"http://id.loc.gov/authorities/genreForms/gf2011026728"},{"@id":"http://id.loc.gov/authorities/genreForms/gf2011026743"},{"@id":"http://id.loc.gov/authorities/genreForms/gf2011026752"},{"@id":"http://id.loc.gov/authorities/genreForms/gf2011026755"},{"@id":"http://id.loc.gov/authorities/genreForms/gf2011026756"},{"@id":"http://id.loc.gov/authorities/genreForms/gf2012025007"},{"@id":"http://id.loc.gov/authorities/genreForms/gf2012025033"},{"@id":"http://id.loc.gov/authorities/genreForms/gf2014026012"},{"@id":"http://id.loc.gov/authorities/genreForms/gf2018026068"},{"@id":"http://id.loc.gov/authorities/genreForms/gf2021026021"},{"@id":"http://id.loc.gov/authorities/genreForms/gf2022026093"},{"@id":"http://id.loc.gov/authorities/genreForms/gf2023026077"},{"@id":"http://id.loc.gov/authorities/genreForms/gf2024026051"},{"@id":"http://id.loc.gov/authorities/genreForms/gf2024026056"},{"@id":"http://id.loc.gov/authorities/genreForms/gf2011026386"},{"@id":"http://id.loc.gov/authorities/genreForms/gf2023026143"}],"madsrdf:hasCloseExternalAuthority":[{"@id":"http://data.bnf.fr/ark:/12148/cb11952385d"},{"@id":"http://datos.bne.es/resource/XX5318422"},{"@id":"http://id.worldcat.org/fast/1423704"}],"madsrdf:adminMetadata":[{"@id":"_:b156iddOtlocdOtgovauthoritiesgenreFormsgf2011026387"},{"@id":"_:b164iddOtlocdOtgovauthoritiesgenreFormsgf2011026387"}]},{"@id":"_:b8iddOtlocdOtgovauthoritiesgenreFormsgf2011026387","@type":"madsrdf:GenreFormElement","madsrdf:elementValue":{"@language":"en","@value":"Maps"}},{"@id":"_:b39iddOtlocdOtgovauthoritiesgenreFormsgf2011026387","@type":"madsrdf:Source","madsrdf:citationStatus":"found","madsrdf:citationSource":"Glossary of the mapping sciences, 1994:","madsrdf:citationNote":{"@language":"en","@value":"map (1. a conventional representation, usually on a plane surface and at an established scale, of the physical features (natural, artificial, or both) of a part or whole of the Earth''s surface by means of signs and symbols and with the means of orientation indicated; 2. a conventional representation, usually on a plane surface, and at an established scale, of the physical features (natural, artificial, or both) of a part or whole of the celestial sphere by means of signs and symbols and with the means of orientation indicated. Because of the widespread use of such maps for navigation, a map of the celestial sphere is often referred to as a star chart. The type of information a map is designed primarily to convey is frequently indicated by an adjective, to distinguish it from other types) chart (a map designed for use in navigation; applied chiefly to maps made primarily for nautical or aeronautical navigation, and to maps of the heavens)"}},{"@id":"_:b63iddOtlocdOtgovauthoritiesgenreFormsgf2011026387","@type":"madsrdf:Source","madsrdf:citationStatus":"found","madsrdf:citationSource":"University of Washington. University of Washington, plan of present campus. Scale [ca. 1:2,400], 1959."},{"@id":"_:b19iddOtlocdOtgovauthoritiesgenreFormsgf2011026387","@type":"madsrdf:GenreFormElement","madsrdf:elementValue":{"@language":"en","@value":"Charts (Cartography)"}},{"@id":"_:b55iddOtlocdOtgovauthoritiesgenreFormsgf2011026387","@type":"madsrdf:Source","madsrdf:citationStatus":"found","madsrdf:citationSource":"OED online, Dec. 1, 2009:","madsrdf:citationNote":{"@language":"en","@value":"map (A drawing or other representation of the earth''s surface or a part of it made on a flat surface, showing the distribution of physical or geographical features (and often also including socio-economic, political, agricultural, meteorological, etc., information), with each point in the representation corresponding to an actual geographical position according to a fixed scale or projection; a similar representation of the positions of stars in the sky, the surface of a planet, or the like) physical map [no entry]"}},{"@id":"_:b13iddOtlocdOtgovauthoritiesgenreFormsgf2011026387","@type":["madsrdf:GenreForm","madsrdf:Variant"],"madsrdf:variantLabel":{"@language":"en","@value":"Charts (Cartography)"},"madsrdf:elementList":{"@list":[{"@id":"_:b19iddOtlocdOtgovauthoritiesgenreFormsgf2011026387"}]}},{"@id":"_:b81iddOtlocdOtgovauthoritiesgenreFormsgf2011026387","@type":"madsrdf:Source","madsrdf:citationStatus":"found","madsrdf:citationSource":"Art & architecture thesaurus online, Sept. 1, 2016","madsrdf:citationNote":{"@language":"en","@value":"(plans (maps). Note: Refers to maps depicting a relatively small district or region, such as a town or city, drawn on a large scale and with considerable detail. For maps of larger regions, use \\"topographic maps\\" or \\"chorographic maps.\\" For depictions of smaller plots of land, particularly as related to the planning of architecture, use \\"site plans.\\" For representations of buildings or objects depicted on a horizontal plane, use \\"plans (orthographic projections).\\" BT maps (documents))"}},{"@id":"_:b89iddOtlocdOtgovauthoritiesgenreFormsgf2011026387","@type":"madsrdf:Source","madsrdf:citationStatus":"found","madsrdf:citationSource":"Reitz, J.M. ODLIS : online dictionary for library and information science, Sept. 1, 2016","madsrdf:citationNote":{"@language":"en","@value":"(plan: A large-scale (1:5,000 or larger) detailed map of a relatively small area, such as a university campus, small park, garden, battlefield, or site on which a building or complex of buildings stands, showing relative positions on a horizontal plane parallel to the picture plane and features drawn to scale with little generalization)"}},{"@id":"_:b69iddOtlocdOtgovauthoritiesgenreFormsgf2011026387","@type":"madsrdf:Source","madsrdf:citationStatus":"found","madsrdf:citationSource":"00557339: George Washington University. 1999 campus plan, George Washington University at Mount Vernon College. Scale [ca. 1:1,750], 1999?"},{"@id":"_:b22iddOtlocdOtgovauthoritiesgenreFormsgf2011026387","@type":["madsrdf:GenreForm","madsrdf:Variant"],"madsrdf:variantLabel":{"@language":"en","@value":"Plans (Maps)"},"madsrdf:elementList":{"@list":[{"@id":"_:b28iddOtlocdOtgovauthoritiesgenreFormsgf2011026387"}]}},{"@id":"_:b31iddOtlocdOtgovauthoritiesgenreFormsgf2011026387","@type":"madsrdf:Source","madsrdf:citationStatus":"found","madsrdf:citationSource":"Glossary of mapping, charting, and geodetic terms, 1973:","madsrdf:citationNote":{"@language":"en","@value":"map (a graphic representation, usually on a plane surface and at an established scale, of natural and manmade features on or under the surface of the earth or other planetary body. The features are positioned as accurately as possible, usually relative to a coordinate reference system. Also, a graphic representation of a part or the whole of the celestial sphere) physical map [no entry]"}},{"@id":"_:b47iddOtlocdOtgovauthoritiesgenreFormsgf2011026387","@type":"madsrdf:Source","madsrdf:citationStatus":"found","madsrdf:citationSource":"Wikipedia, Dec. 1, 2009","madsrdf:citationNote":{"@language":"en","@value":"(physical map: redirect to map: a visual representation of an area; a symbolic depiction highlighting relationships between elements of that space such as objects, regions, and themes)"}},{"@id":"_:b75iddOtlocdOtgovauthoritiesgenreFormsgf2011026387","@type":"madsrdf:Source","madsrdf:citationStatus":"found","madsrdf:citationSource":"2008620665: Quail Map Company. Exeter street plan, ©2007."},{"@id":"_:b28iddOtlocdOtgovauthoritiesgenreFormsgf2011026387","@type":"madsrdf:GenreFormElement","madsrdf:elementValue":{"@language":"en","@value":"Plans (Maps)"}},{"@id":"_:b164iddOtlocdOtgovauthoritiesgenreFormsgf2011026387","@type":"ri:RecordInfo","ri:recordChangeDate":{"@type":"xsd:dateTime","@value":"2019-01-23T11:21:14"},"ri:recordStatus":{"@type":"xsd:string","@value":"revised"},"ri:recordContentSource":{"@id":"http://id.loc.gov/vocabulary/organizations/dlc"},"ri:languageOfCataloging":{"@id":"http://id.loc.gov/vocabulary/iso639-2/eng"}}],"@context":{"bf":"http://id.loc.gov/ontologies/bibframe/","bflc":"http://id.loc.gov/ontologies/bflc/","cs":"http://purl.org/vocab/changeset/schema#","dcterms":"http://purl.org/dc/terms/","foaf":"http://xmlns.com/foaf/0.1/","identifiers":"http://id.loc.gov/vocabulary/identifiers/","lcc":"http://id.loc.gov/ontologies/lcc#","madsrdf":"http://www.loc.gov/mads/rdf/v1#","owl":"http://www.w3.org/2002/07/owl#","rdf":"http://www.w3.org/1999/02/22-rdf-syntax-ns#","rdfs":"http://www.w3.org/2000/01/rdf-schema#","ri":"http://id.loc.gov/ontologies/RecordInfo#","skos":"http://www.w3.org/2004/02/skos/core#","skosxl":"http://www.w3.org/2008/05/skos-xl#","vs":"http://www.w3.org/2003/06/sw-vocab-status/ns#","xsd":"http://www.w3.org/2001/XMLSchema#"}}');
