e":"Silverstein, Virginia"},"madsrdf:elementList":{"@list":[{"@id":"_:b32iddOtlocdOtgovauthoritiesnamesn79039766"}]},"bflc:marcKey":{"@language":"zxx-latn","@value":"4001 $aSilverstein, Virginia"}},{"@id":"_:b67iddOtlocdOtgovauthoritiesnamesn79039766","@type":"madsrdf:Source","madsrdf:citationStatus":"found","madsrdf:citationSource":"Web site for silversteinbooks.com, October 22, 2013:","madsrdf:citationNote":"About the Silversteins (Virginia Silverstein was an only child and grew up in Philadelphia. She majored in chemistry and studied languages in her spare time. She met her husband, author Alvin Silverstein, in the chemistry lab at Penn when she was a senior and he was a graduate student. That led to marriage, six children, nine grandchildren, and more than 200 published books, mainly on science and health topics for children and adults. Two of their children, Bob and Laura, have coauthored a number of books with them. Virginia has also worked as a translator of Russian science articles and books. She and her husband live in rural New Jersey)"},{"@id":"_:b37iddOtlocdOtgovauthoritiesnamesn79039766","@type":"madsrdf:Source","madsrdf:citationStatus":"found","madsrdf:citationSource":"Life in the universe, 1967."},{"@id":"_:b94iddOtlocdOtgovauthoritiesnamesn79039766","@type":"ri:RecordInfo","ri:recordChangeDate":{"@type":"xsd:dateTime","@value":"2025-08-04T23:53:14"},"ri:recordStatus":{"@type":"xsd:string","@value":"revised"},"ri:recordContentSource":{"@id":"http://id.loc.gov/vocabulary/organizations/ocolc"},"ri:languageOfCataloging":{"@id":"http://id.loc.gov/vocabulary/iso639-2/eng"}}],"@context":{"bf":"http://id.loc.gov/ontologies/bibframe/","bflc":"http://id.loc.gov/ontologies/bflc/","cs":"http://purl.org/vocab/changeset/schema#","dcterms":"http://purl.org/dc/terms/","foaf":"http://xmlns.com/foaf/0.1/","identifiers":"http://id.loc.gov/vocabulary/identifiers/","lcc":"http://id.loc.gov/ontologies/lcc#","madsrdf":"http://www.loc.gov/mads/rdf/v1#","owl":"http://www.w3.